// 生成守护 —— QR 助手快捷按钮：点一下直接跳到扩展页，并把生成守护的面板展开
eventOn(getButtonEvent('生成守护'), () => {
  const W = window.parent || window;
  const gg = W.GenerationGuardian;
  if (!gg) {
    (W.toastr || window.toastr)?.warning?.('没找到「生成守护」扩展，先在酒馆里把它装上');
    return;
  }
  if (typeof gg.openPanel === 'function') {
    gg.openPanel();
  } else {
    (W.toastr || window.toastr)?.info?.('扩展版本旧了，更新到 1.3.14 以上再点我');
  }
});
